    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Ash turns to Wren, ready to discuss the mill.",
    "cited_fact_keys": ["reaction:438d283a-d795-5133-8f55-561b505e6bde"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tried to communicate with Ash about the dawn patrol, but Ash was waiting for something else.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:wait"],
    "text": "Wren waits patiently, his eyes fixed on the horizon."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "text": "Ash tries to engage Wren in conversation, bringing up the topic of the dawn patrol."
  },
  {
    "kind": "dialogue",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": "b1967f05-16cc-417b-baf1-3d116ade29e0",
    "text": "Hey Wren, have you thought about the dawn patrol?"
  },
  {
    "kind": "action",
    "cited_fact_keys": ["attempt:wait"],
    "text": "Wren shifts his weight, still focused on the horizon."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "text": "Ash persists, trying to get Wren's attention."
  },
  {
    "kind": "dialogue",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": "b1967f05-16cc-417b-baf1-3d116ade29e0",
    "text": "Wren, the dawn patrol, remember we talked about it?"
  },
  {
    "kind": "action",
    "cited_fact_keys": ["attempt:wait"],
    "text": "Wren blinks, finally acknowledging Ash's presence."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "text": "Ash feels a glimmer of hope that Wren might respond."
  }
]

[
  {
    "kind": "narration",
    "text": "Wren waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Ash tries to engage Wren in conversation about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
