  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren waits for Ash's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"The mill road is clear.\" Wren informs Ash.",
    "cited_fact_keys": ["reaction:f4022018-ee77-55b9-ac47-fb4d3c4177cd"],
