  },
  {
    "kind": "narration",
    "text": "Ash waited for Wren to speak.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash said to Wren.",
    "cited_fact_keys": ["reaction:1b79501b-c989-552f-a9ca-4f80fbeb6ffa"],
    "speaker_id": "b64df113-d89f-4b2f-b0c3-747e4c960c90"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits, his gaze fixed on the distant lighthouse.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren tries to engage Ash in conversation.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "6403d03b-baa4-4beb-855f-90342026a08c",
    "text": "\"Old Marlow, if the lamp is still lit.\" Ash responds to Wren's query about the lighthouse's night keeper.",
    "cited_fact_keys": ["reaction:fd6d665f-0c06-550b-94f2-db31c1bda453"]
  }
]
